// Explicit legacy fixtures for regression tests only. Never imported by the application.
import {formatWeightMicros} from '../../../interno/hortifruti/weight-input.js';
import {calculateLine,formatDecimal,parseUnitCount} from './hortifruti-model.js';
export function weighingSummary(item,purchaseUnit=''){const boxes=item.weighMode==='boxes'?item.boxes?.length||0:null;let countLabel=boxes===null?'Caixas: —':`${boxes} caixa${boxes===1?'':'s'}`;if(String(purchaseUnit).toUpperCase()==='UN'&&boxes===null){try{const count=parseUnitCount(item.unitCount);countLabel=count===null?'Unidades: —':`${count} unidade${count===1?'':'s'}`;}catch{countLabel='Verificar unidades';}}try{const weight=false?(item._computed||{}):calculateLine({...item,total:'',unitCost:'',basis:'total',unitCount:''});if(weight.invalid)return {boxCount:boxes,countLabel,weightMicros:null,weightLabel:'Verificar peso',incomplete:true,invalid:true};return {boxCount:boxes,countLabel,weightMicros:weight.quantityMicros,weightLabel:weight.quantityMicros?`${formatWeightMicros(weight.quantityMicros)} kg`:'A pesar',incomplete:weight.boxesIncomplete,invalid:false};}catch{return {boxCount:boxes,countLabel,weightMicros:null,weightLabel:'Verificar peso',incomplete:true,invalid:true};}}
/** Visibility only: the controls, listeners and raw draft values are never replaced. */
export function setWeighingExpanded(toggle,panel,expanded){if(!expanded&&panel.contains(panel.ownerDocument?.activeElement))toggle.focus({preventScroll:true});panel.hidden=!expanded;toggle.setAttribute('aria-expanded',String(expanded));}
